begin;
drop policy hide_unstarted_mock on public.generated_questions;
create policy hide_unstarted_mock on public.generated_questions as restrictive for select to authenticated using(not exists(select 1 from public.mock_exam_questions mq join public.mock_exams m on m.id=mq.mock_id where mq.question_id=generated_questions.id and m.status in('building','ready')));
create table public.worker_heartbeats(id text primary key,last_seen timestamptz not null,version text not null);alter table public.worker_heartbeats enable row level security;revoke all on public.worker_heartbeats from public,anon,authenticated;grant all on public.worker_heartbeats to service_role;
create or replace function public.reserve_ai_request(p_user uuid,p_user_limit integer,p_global_limit integer) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin
if p_global_limit is null or p_global_limit not between 1 and 10000 or p_user_limit is null or p_user_limit not between 1 and 1000 then raise exception 'INVALID_AI_LIMIT';end if;
if not public.consume_revision_usage(p_user,'ai_requests',p_user_limit) then raise exception 'AI_USER_LIMIT';end if;insert into public.ai_request_days values((now() at time zone 'UTC')::date,1) on conflict(day) do update set used=public.ai_request_days.used+1 where public.ai_request_days.used<p_global_limit returning used into n;if not found then raise exception 'AI_GLOBAL_LIMIT';end if;return true;end $$;
create function public.force_document_review() returns trigger language plpgsql set search_path='' as $$begin new.needs_review:=true;return new;end $$;create trigger review_all_ocr_pages before insert on public.document_pages for each row execute function public.force_document_review();
create or replace function public.review_extracted_item(p_id uuid,p_user uuid,p_prompt text,p_marks integer) returns boolean language plpgsql security definer set search_path='' as $$declare did uuid;kind text;begin
select e.document_id,d.kind into did,kind from public.extracted_questions e join public.documents d on d.id=e.document_id where e.id=p_id and e.user_id=p_user;if not found then raise exception 'ITEM_NOT_FOUND';end if;
if p_prompt is null or length(trim(p_prompt)) not between 1 and 20000 or(p_marks is not null and p_marks not between 1 and 100) or(kind='paper' and p_marks is null) then raise exception 'INVALID_REVIEW';end if;
update public.extracted_questions set prompt=trim(p_prompt),marks=p_marks,needs_review=false,reviewed_at=clock_timestamp() where id=p_id and user_id=p_user;
if not exists(select 1 from public.extracted_questions where document_id=did and needs_review) and not exists(select 1 from public.document_pages where document_id=did and needs_review) then update public.documents set status='ready' where id=did and user_id=p_user;end if;return true;end $$;
create function public.review_document_page(p_doc uuid,p_user uuid,p_page integer,p_text text) returns boolean language plpgsql security definer set search_path='' as $$begin
if p_text is null or length(p_text)>100000 then raise exception 'INVALID_PAGE_TEXT';end if;update public.document_pages set text_content=p_text,needs_review=false where document_id=p_doc and user_id=p_user and page_number=p_page;if not found then raise exception 'PAGE_NOT_FOUND';end if;
if not exists(select 1 from public.extracted_questions where document_id=p_doc and needs_review) and not exists(select 1 from public.document_pages where document_id=p_doc and needs_review) then update public.documents set status='ready' where id=p_doc and user_id=p_user;end if;return true;end $$;
create function public.attach_reviewed_answer(p_attempt uuid,p_user uuid,p_document uuid,p_label text,p_version integer) returns public.attempts language plpgsql security definer set search_path='' as $$declare answer_text text;a public.attempts;begin
select e.prompt into answer_text from public.extracted_questions e join public.documents d on d.id=e.document_id where e.document_id=p_document and e.user_id=p_user and e.question_label=p_label and not e.needs_review and d.kind='answer_sheet' and d.status='ready';if not found then raise exception 'REVIEWED_ANSWER_NOT_FOUND';end if;
a:=public.save_revision_answer_v2(p_attempt,p_user,answer_text,p_version);update public.attempts set answer_document_id=p_document where id=a.id and user_id=p_user returning * into a;return a;end $$;
create function public.review_revision_job(p_id uuid,p_worker uuid,p_attempt integer,p_reason text) returns boolean language plpgsql security definer set search_path='' as $$declare j public.jobs;begin
j:=public.assert_revision_lease(p_id,p_worker,p_attempt);if p_reason is null or p_reason !~ '^[A-Z0-9_]{3,80}$' then raise exception 'INVALID_REASON';end if;
if j.kind='mark_attempt' then update public.attempts set status='review' where id=(j.payload->>'attempt_id')::uuid and user_id=j.user_id and status in('submitted','marking');elsif j.kind='build_mock' then update public.mock_exams set status='review' where id=(j.payload->>'mock_id')::uuid and user_id=j.user_id and status='building';elsif j.kind='process_document' then update public.documents set status='review',error_code=p_reason where id=(j.payload->>'document_id')::uuid and user_id=j.user_id and status in('queued','processing');end if;
return public.finish_revision_job(j.id,p_worker,p_attempt,jsonb_build_object('reason',p_reason),'review');end $$;
create function public.retry_revision_pipeline(p_id uuid,p_worker uuid,p_attempt integer,p_reason text) returns boolean language plpgsql security definer set search_path='' as $$declare j public.jobs;begin
j:=public.assert_revision_lease(p_id,p_worker,p_attempt);perform public.retry_revision_job(j.id,p_worker,p_attempt,p_reason);
if j.attempt_count>=3 then if j.kind='mark_attempt' then update public.attempts set status='review' where id=(j.payload->>'attempt_id')::uuid and user_id=j.user_id and status in('submitted','marking');elsif j.kind='build_mock' then update public.mock_exams set status='failed' where id=(j.payload->>'mock_id')::uuid and user_id=j.user_id and status='building';elsif j.kind='process_document' then update public.documents set status='failed',error_code=p_reason where id=(j.payload->>'document_id')::uuid and user_id=j.user_id and status in('queued','processing');end if;end if;return true;end $$;
revoke all on function public.force_document_review() from public,anon,authenticated;
do $$declare f record;begin for f in select oid::regprocedure sig from pg_proc where pronamespace='public'::regnamespace and proname in('review_document_page','attach_reviewed_answer','review_revision_job','retry_revision_pipeline') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
commit;
